import{z as s,x as l,o as e,c as p,q as r,j as n,D as t,d as A,s as o,S as i,b as a}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"常数优化","description":"","frontmatter":{"title":"常数优化","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ae-constant-optimization.md","filePath":"cs/ae-constant-optimization.md","lastUpdated":1791413859000}'),d={name:"cs/ae-constant-optimization.md"};function D(m,E,C,u,c,F){const B=l("Mermaid");return e(),p("div",null,[E[2]||(E[2]=r('<h1 id="常数优化" tabindex="-1">常数优化 <a class="header-anchor" href="#常数优化" aria-label="Permalink to &quot;常数优化&quot;">​</a></h1><div class="epigraph"><p>对那 3% 值得优化的代码，程序员不应放弃任何一个常数；难处从来不在省，而在知道哪 3% 值得省。</p><footer>—— 据 Knuth, Structured Programming with go to Statements, 1974 整理</footer></div><p><a href="/cs/ae-selection-engineering">上一课</a>把选型钉在四问与交叉点上：阶定下来之后，剩下的战场就是常数。同一算法类的两条实现，实测可以差五到十倍——本课处理的就是这个差距。立场先立好：先测量后动手，热点在哪、常数由什么构成，profiler 说了算；然后按「减指令数、降单条指令成本、减分支」三层把冗余剥掉。后课默认你已带着这条测量先行的纪律。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>常数从哪来：每条源语句展开成若干条指令，而指令之间延迟与吞吐差着量级；其上再叠冗余计算——重复求值的子表达式、循环内不变的外提物、本可移位代换的除法。缺口是：在不动渐近阶的前提下，把每迭代指令数与每指令平均成本压下来。不这么做会错在两个方向：凭直觉重写，把编译器本来就会做的代换手工抄一遍，白丢可读性；或在真正的热点上做了修改却不复测，把噪声当成收益，优化效果从此成了传说。</p><p><span class="marginnote">术语翻译：强度削减就是用「便宜运算的组合」来替换「贵运算」——除以 8 换成右移 3 位，对 8 取模换成与 7 按位与，乘 64 换成左移 6 位。省的不是阶，是把一条 20 多周期的指令换成一条 1 周期的指令。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>第一步，测量定位。profiler 与操作计数器找出被反复执行的核心循环，只有它配得上手工改动；先干测（数操作）再计时，收益归因才有依据。</p><p>第二步，消冗余。循环不变量外提：不随迭代变的计算挪到循环外，判据正是<a href="/cs/loop-invariant">循环不变式</a>「每轮前后都成立、循环结束时可用的那部分」；公共子表达式只算一次；循环内不变的小函数调用内联或挪出。</p><p>第三步，降单条指令成本。强度削减：乘除换移位与加减；多项式求值用 Horner 法 \\(p(x)=a_0+x\\,(a_1+x\\,(a_2+\\cdots))\\)，把每项两次乘法降为每阶一次乘一加，\\(n\\) 阶多项式从 \\(2n\\) 次乘降到 \\(n\\) 次。除法与取模是最贵的常规整数运算，除以常数时换成移位与掩码。</p><p>第四步，减分支。深度流水线上一次误预测罚十几到二十个周期；高度可预测的分支留着不动，数据依赖的极值与符号判断改写成无分支形式——具体技巧留给位运算一课。</p>',11)),(e(),n(i,null,{default:t(()=>[o(B,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20M%5B%22%E6%B5%8B%E9%87%8F%E5%AE%9A%E4%BD%8D%E7%83%AD%E7%82%B9%22%5D%20--%3E%20R%5B%22%E6%B6%88%E5%86%97%E4%BD%99%EF%BC%9A%E5%A4%96%E6%8F%90%E4%B8%8E%E5%A4%8D%E7%94%A8%22%5D%0A%20%20R%20--%3E%20C%5B%22%E9%99%8D%E6%8C%87%E4%BB%A4%E6%88%90%E6%9C%AC%EF%BC%9A%E5%BC%BA%E5%BA%A6%E5%89%8A%E5%87%8F%E3%80%81Horner%22%5D%0A%20%20C%20--%3E%20B%5B%22%E5%87%8F%E5%88%86%E6%94%AF%E4%B8%8E%E8%AF%AF%E9%A2%84%E6%B5%8B%22%5D%0A%20%20B%20--%3E%20T%5B%22%E5%A4%8D%E6%B5%8B%EF%BC%9A%E6%94%B6%E7%9B%8A%E5%85%A5%E8%B4%A6%E6%88%96%E5%9B%9E%E9%80%80%22%5D%0A%20%20T%20--%3E%7C%E6%94%B6%E7%9B%8A%E4%B8%8D%E5%AE%9E%7C%20M%0A%20%20T%20--%3E%7C%E6%94%B6%E7%9B%8A%E7%A1%AE%E8%AE%A4%7C%20KEEP%5B%22%E5%86%99%E8%BF%9B%E6%B3%A8%E9%87%8A%E4%B8%8E%E5%9F%BA%E5%87%86%22%5D%0A"})]),fallback:t(()=>[...E[0]||(E[0]=[A(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[A("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,"常数可写成三因子：每迭代指令数、每指令平均成本、迭代数。消冗余减第一个因子；强度削减与分支改造减第二个；渐近阶钉死第三个。这套账解释了优先级：迭代数是阶的事，上一课已定；剩下的两层里，减一条昂贵指令（除法）通常胜过省三条便宜指令（加法）。",-1)),E[5]||(E[5]=a("p",null,[A("现代编译器在基本块内已经做强度削减与外提，所以人手该做的是它跨不过去的那部分：别名不确定时它不敢外提，溢出语义改变结果时它不敢代换——把写法整理成编译器能证明的形式，才是有效常数优化。也要认得这条路的尽头：当「常数技巧」本质是反复利用同一批子问题的结果、而且结果可以存下时，它就升级为渐近改进，大整数乘法从 \\(O(n^2)\\) 走到 "),a("a",{href:"/cs/karatsuba"},"Karatsuba"),A(" 的 \\(O(n^{\\log_2 3})\\) 正是样本——本课止步于阶不变的那些改动。")],-1)),E[6]||(E[6]=a("p",null,[a("span",{class:"marginnote"},"量级账：寄存器加法约 1 个周期，32 位整数除法在常见 x86 上约 20–30 个周期，分支误预测罚约 15–20 个周期。热循环里一次「除以常数改移位」在百万次迭代上省出毫秒级；而 \\(i\\cdot 8\\) 这类代换编译器必做，人工重抄只是给 reviewer 添噪。")],-1)),E[7]||(E[7]=a("p",null,"方法一节的图回答「优化按什么流程走」，下面这张回答另一个问题：面对热点里的一处改动，怎么判断它归不归你手工做。",-1)),(e(),n(i,null,{default:t(()=>[o(B,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20H%5B%22%E7%83%AD%E7%82%B9%E5%BE%AA%E7%8E%AF%E9%87%8C%E7%9A%84%E4%B8%80%E5%A4%84%E5%80%99%E9%80%89%E6%94%B9%E5%8A%A8%22%5D%20--%3E%20Q0%7B%22%E5%8A%A8%E7%9A%84%E6%98%AF%E8%BF%AD%E4%BB%A3%E6%95%B0(%E9%98%B6)%3F%22%7D%0A%20%20Q0%20--%20%22%E6%98%AF%22%20--%3E%20OOM%5B%22%E8%B6%85%E5%87%BA%E6%9C%AC%E8%AF%BE%3A%20%E5%9B%9E%E9%80%89%E5%9E%8B%E8%AF%BE%E6%8D%A2%E7%AE%97%E6%B3%95%22%5D%0A%20%20Q0%20--%20%22%E5%90%A6%22%20--%3E%20Q1%7B%22%E7%BC%96%E8%AF%91%E5%99%A8%E6%9C%AC%E6%9D%A5%E5%B0%B1%E4%BC%9A%E5%81%9A%3F%22%7D%0A%20%20Q1%20--%20%22%E4%BC%9A%2C%20%E5%A6%82%20i*8%20%E6%8D%A2%E7%A7%BB%E4%BD%8D%22%20--%3E%20SKIP%5B%22%E4%B8%8D%E6%8A%84%E5%AE%83%E7%9A%84%E6%B4%BB%2C%20%E4%BF%9D%E4%BD%8F%E5%8F%AF%E8%AF%BB%E6%80%A7%22%5D%0A%20%20Q1%20--%20%22%E4%B8%8D%E4%BC%9A%3A%20%E5%88%AB%E5%90%8D%E6%88%96%E6%BA%A2%E5%87%BA%E8%AF%AD%E4%B9%89%E6%8C%A1%E4%BD%8F%E5%AE%83%22%20--%3E%20Q2%7B%22%E5%8A%A8%E5%93%AA%E4%B8%AA%E5%B8%B8%E6%95%B0%E5%9B%A0%E5%AD%90%3F%22%7D%0A%20%20Q2%20--%3E%20I%5B%22%E5%87%8F%E6%8C%87%E4%BB%A4%E6%95%B0%3A%20%E5%A4%96%E6%8F%90%2F%E5%85%AC%E5%85%B1%E5%AD%90%E8%A1%A8%E8%BE%BE%E5%BC%8F%22%5D%0A%20%20Q2%20--%3E%20P%5B%22%E9%99%8D%E5%8D%95%E6%9D%A1%E6%88%90%E6%9C%AC%3A%20%E9%99%A4%E6%B3%95%E6%8D%A2%E7%A7%BB%E4%BD%8D%22%5D%0A%20%20I%20--%3E%20T%5B%22%E5%A4%8D%E6%B5%8B%3A%20%E6%94%B6%E7%9B%8A%E7%A1%AE%E8%AE%A4%E6%89%8D%E5%85%A5%E8%B4%A6%22%5D%0A%20%20P%20--%3E%20T%0A"})]),fallback:t(()=>[...E[1]||(E[1]=[A(" Loading... ",-1)])]),_:1})),E[8]||(E[8]=r('<p><span class="marginnote">数字实例：Horner 法算 \\(p(2)\\)，\\(p(x)=4x^3+3x^2+2x+1\\)——朴素法要算 \\(x^2,x^3\\) 再逐项相乘，共 6 次乘法；Horner 写成 \\(((4\\cdot 2+3)\\cdot 2+2)\\cdot 2+1\\)，3 次乘 3 次加得 49。阶升到 \\(n\\)，乘法从 \\(2n\\) 次降到 \\(n\\) 次，且格式规整到编译器也认得。</span></p><p><span class="marginnote">直觉类比：常数三因子像月账单总额 = 每单成本 × 单数。迭代数（单数）是选型课定下的，这里只能砍「每单成本」——先砍最贵的那一单（一条 20 多周期的除法），胜过在 1 周期的加法上抠出三条；账要复测，不然省下的可能只是机器打了个盹。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要抢编译器的活：它做得对、可移植，手工版反而可能在别的后端上更慢。手工改写还要防「挡住自动向量化」：为省一条指令引入的早退分支或复杂寻址，可能让整段循环失去向量化资格，见<a href="/cs/auto-vectorization">自动向量化</a>。可读性是预算的一部分：每处手工优化都要配基准与注释，否则下一位维护者会把它「修」回去。本课不碰数据在内存里的摆放——那是下一课的主题，也是常数账里常常最大的一项。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>常数 = 每迭代指令数 × 每指令平均成本；先测热点，再动刀，收益复测后入账。</li><li>消冗余三件套：不变量外提、公共子表达式、Horner 化求值。</li><li>除法与不可预测分支是最贵的单条指令；强度削减省的是周期，不是阶。</li><li>编译器会做的代换留给编译器；人做它因别名或溢出语义而做不了的那部分。</li><li>常数技巧一旦变成「存下并复用子问题」，就升级为渐近改进，Karatsuba 是边界样本。</li><li>出处：Knuth, <em>Structured Programming with go to Statements</em>, 1974；据 Bentley, <em>Writing Efficient Programs</em>, 1982 的优化口径整理。</li></ul>',6))])}const _=s(d,[["render",D]]);export{h as __pageData,_ as default};
